package com.vinaxmart.controller; import com.vinaxmart.entity.*;import com.vinaxmart.repository.*;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.util.*; @RestController @RequestMapping("/api/wishlist") public class WishlistController{final WishlistItemRepository r;final UserRepository u;final ProductRepository p;WishlistController(WishlistItemRepository r,UserRepository u,ProductRepository p){this.r=r;this.u=u;this.p=p;}User user(Authentication a){return u.findByEmail(a.getName()).orElseThrow();}@GetMapping List<WishlistItem> all(Authentication a){return r.findByUser(user(a));}@PostMapping("/{pid}") WishlistItem add(Authentication a,@PathVariable Long pid){User x=user(a);Product q=p.findById(pid).orElseThrow();return r.save(r.findByUserAndProduct(x,q).orElse(WishlistItem.builder().user(x).product(q).build()));}@DeleteMapping("/{id}") void del(@PathVariable Long id){r.deleteById(id);}}